/* ============================================================
    archivo: /modulos/papeletas/js/bootstrap.bundle.min.js

   BOOTSTRAP BUNDLE LITE – ERP PHP 5.6
   Funciones esenciales para modales
   ============================================================ */

(function(){

    /* ------------------------------------------------------------
       Abrir modal
       ------------------------------------------------------------ */
    function openModal(modal) {
        if (!modal) return;

        modal.classList.add("show");
        modal.style.display = "block";

        // Crear backdrop
        var backdrop = document.createElement("div");
        backdrop.className = "modal-backdrop";
        backdrop.style.position = "fixed";
        backdrop.style.top = "0";
        backdrop.style.left = "0";
        backdrop.style.width = "100%";
        backdrop.style.height = "100%";
        backdrop.style.background = "rgba(0,0,0,.5)";
        backdrop.style.zIndex = "9998";
        backdrop.setAttribute("data-backdrop", modal.id);

        document.body.appendChild(backdrop);
    }

    /* ------------------------------------------------------------
       Cerrar modal
       ------------------------------------------------------------ */
    function closeModal(modal) {
        if (!modal) return;

        modal.classList.remove("show");
        modal.style.display = "none";

        // Eliminar backdrop
        var backdrops = document.querySelectorAll("[data-backdrop='" + modal.id + "']");
        for (var i = 0; i < backdrops.length; i++) {
            backdrops[i].parentNode.removeChild(backdrops[i]);
        }
    }

    /* ------------------------------------------------------------
       Detectar botones con data-bs-dismiss="modal"
       ------------------------------------------------------------ */
    document.addEventListener("click", function(e){
        var btn = e.target.closest("[data-bs-dismiss='modal']");
        if (btn) {
            var modal = btn.closest(".modal");
            closeModal(modal);
        }
    });

    /* ------------------------------------------------------------
       API pública para abrir modales desde JS
       ------------------------------------------------------------ */
    window.bootstrapLite = {
        show: function(id){
            var modal = document.getElementById(id);
            openModal(modal);
        },
        hide: function(id){
            var modal = document.getElementById(id);
            closeModal(modal);
        }
    };

})();
